package org.canpshell.mobile;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import hev.htproxy.TProxyService;
/** Local user-consented TCP VPN. Never started by cloud/RPC and never auto-replaces a VPN. */
public final class AndroidMachineVpnService extends VpnService {
 static volatile String state="未开启";private static volatile AndroidMachineVpnService active;
 private ParcelFileDescriptor tunnel;private AndroidVpnSocks socks;private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();private volatile boolean stopping;
 static boolean active(){return active!=null;}
 static boolean available(){if(Build.VERSION.SDK_INT<29)return false;try{TProxyService.TProxyIsRunning();return true;}catch(LinkageError e){return false;}}
 static boolean anotherVpn(Context context){if(active())return false;ConnectivityManager cm=context.getSystemService(ConnectivityManager.class);for(Network n:cm.getAllNetworks()){NetworkCapabilities cap=cm.getNetworkCapabilities(n);if(cap!=null&&cap.hasTransport(NetworkCapabilities.TRANSPORT_VPN))return true;}return false;}
 public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"stop".equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}if(active!=null)return START_NOT_STICKY;active=this;foreground("正在连接所选出口");worker.execute(()->{synchronized(this){try{if(stopping)return;if(!available())throw new IOException("当前安装包不支持系统网络出口");AndroidNetworkProxy proxy=AndroidAgentService.networkProxy();proxy.port();socks=new AndroidVpnSocks(()->AndroidAgentService.networkProxy().port());
  Builder b=new Builder().setSession("CAgent 机器出口 · TCP").setMtu(1500).addAddress("198.18.0.1",30).addAddress("fdca:6765:6e74::1",126).addRoute("0.0.0.0",0).addRoute("::",0).addDnsServer("198.18.0.2").setBlocking(false);b.addDisallowedApplication(getPackageName());tunnel=b.establish();if(tunnel==null)throw new IOException("需要重新允许 VPN 授权");
  File config=new File(getFilesDir(),"machine-vpn.yml");String yaml="tunnel:\n  name: cagent\n  mtu: 1500\n  ipv4: 198.18.0.1\n  ipv6: 'fdca:6765:6e74::1'\n  icmp: 'off'\nsocks5:\n  address: 127.0.0.1\n  port: "+socks.port()+"\n  udp: 'udp'\nmapdns:\n  address: 198.18.0.2\n  port: 53\n  network: 100.64.0.0\n  netmask: 255.192.0.0\n  cache-size: 4096\nmisc:\n  max-session-count: 24\n  tcp-buffer-size: 32768\n  connect-timeout: 10000\n  log-level: error\n";try(FileOutputStream out=new FileOutputStream(config)){out.write(yaml.getBytes(StandardCharsets.UTF_8));}
  if(!TProxyService.TProxyStartService(config.getAbsolutePath(),tunnel.getFd()))throw new IOException("网络引擎未能启动");state="其他应用 TCP 已使用所选机器出口";foreground(state);worker.scheduleWithFixedDelay(()->{if(stopping)return;try{AndroidAgentService.networkProxy().port();if(!TProxyService.TProxyIsRunning())throw new IOException("网络引擎停止");if(!state.equals("其他应用 TCP 已使用所选机器出口")){state="其他应用 TCP 已使用所选机器出口";foreground(state);}}catch(Exception e){state="出口中断：保持拦截，请恢复出口或手动关闭";foreground(state);}},1,1,TimeUnit.SECONDS);
 }catch(Exception|LinkageError e){state=tunnel==null?"未启动：请检查出口与系统授权":"连接失败：保持拦截，请手动关闭后重试";foreground(state);if(tunnel==null)stopSelf();}}});return START_NOT_STICKY;}
 private void foreground(String text){NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("machine-vpn","机器网络出口",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,AndroidMachineVpnActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,AndroidMachineVpnService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new Notification.Builder(this,"machine-vpn").setSmallIcon(android.R.drawable.stat_sys_upload_done).setContentTitle("CAgent 网络出口").setContentText(text).setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,"关闭",stop).build()).build();startForeground(24445,n);}
 @Override public void onRevoke(){state="系统已撤销 VPN 授权";stopSelf();}
 @Override public synchronized void onDestroy(){stopping=true;if(active==this)active=null;worker.shutdownNow();try{if(available())TProxyService.TProxyStopService();}catch(Exception|LinkageError ignored){}if(socks!=null)socks.close();if(tunnel!=null)try{tunnel.close();}catch(IOException ignored){}stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
